import { useEffect, useRef } from "react";
import { motion, useAnimation, useInView, useReducedMotion } from "framer-motion";

// Reusable fade-up reveal on viewport entrance
export const fadeUp = {
  hidden: { opacity: 0, y: 32 },
  show: (i = 0) => ({
    opacity: 1,
    y: 0,
    transition: {
      delay: i * 0.06,
      duration: 0.7,
      ease: [0.16, 1, 0.3, 1],
    },
  }),
};

export const fadeScale = {
  hidden: { opacity: 0, scale: 0.96 },
  show: (i = 0) => ({
    opacity: 1,
    scale: 1,
    transition: {
      delay: i * 0.06,
      duration: 0.7,
      ease: [0.16, 1, 0.3, 1],
    },
  }),
};

export const stagger = {
  hidden: {},
  show: {
    transition: { staggerChildren: 0.08, delayChildren: 0.05 },
  },
};

export function Reveal({ children, delay = 0, y = 32, className = "", as = "div", ...rest }) {
  const prefersReduced = useReducedMotion();
  const ref = useRef(null);
  const inView = useInView(ref, { once: true, amount: 0.2 });
  const controls = useAnimation();
  useEffect(() => {
    if (inView) controls.start({ opacity: 1, y: 0 });
  }, [inView, controls]);
  // Mount-time fallback: if the section is already inside the viewport
  // (e.g. after client-side navigation + scroll reset), don't wait for
  // the observer — a missed callback previously stranded content at
  // opacity 0 until the user scrolled past it.
  useEffect(() => {
    const el = ref.current;
    if (!el || typeof window === "undefined") return undefined;
    const check = () => {
      const rect = el.getBoundingClientRect();
      if (rect.top < window.innerHeight * 0.95 && rect.bottom > 0) {
        controls.start({ opacity: 1, y: 0 });
      }
    };
    check();
    const timer = setTimeout(check, 350);
    return () => clearTimeout(timer);
  }, [controls]);
  if (prefersReduced) return <div className={className} {...rest}>{children}</div>;
  const MotionComp = motion[as] || motion.div;
  return (
    <MotionComp
      ref={ref}
      initial={{ opacity: 0, y }}
      animate={controls}
      transition={{ delay, duration: 0.8, ease: [0.16, 1, 0.3, 1] }}
      className={className}
      {...rest}
    >
      {children}
    </MotionComp>
  );
}

export function RevealStagger({ children, className = "", ...rest }) {
  const prefersReduced = useReducedMotion();
  const ref = useRef(null);
  const inView = useInView(ref, { once: true, amount: 0.15 });
  const controls = useAnimation();
  useEffect(() => {
    if (inView) controls.start("show");
  }, [inView, controls]);
  useEffect(() => {
    const el = ref.current;
    if (!el || typeof window === "undefined") return undefined;
    const check = () => {
      const rect = el.getBoundingClientRect();
      if (rect.top < window.innerHeight * 0.95 && rect.bottom > 0) {
        controls.start("show");
      }
    };
    check();
    const timer = setTimeout(check, 350);
    return () => clearTimeout(timer);
  }, [controls]);
  if (prefersReduced) return <div className={className} {...rest}>{children}</div>;
  return (
    <motion.div
      ref={ref}
      initial="hidden"
      animate={controls}
      variants={stagger}
      className={className}
      {...rest}
    >
      {children}
    </motion.div>
  );
}

export function StaggerItem({ children, i = 0, className = "", variant = fadeUp, ...rest }) {
  const prefersReduced = useReducedMotion();
  if (prefersReduced) return <div className={className} {...rest}>{children}</div>;
  return (
    <motion.div custom={i} variants={variant} className={className} {...rest}>
      {children}
    </motion.div>
  );
}

// Animated counter that counts up to a target
export function CountUp({ value, format = (v) => v.toLocaleString(), className = "" }) {
  const prefersReduced = useReducedMotion();
  if (prefersReduced) return <span className={className}>{format(value)}</span>;
  return (
    <motion.span
      className={className}
      initial={{ opacity: 0 }}
      whileInView={{ opacity: 1 }}
      viewport={{ once: true }}
      transition={{ duration: 0.6 }}
    >
      {format(value)}
    </motion.span>
  );
}
